style.css:
@-moz-document domain("discord.com") {
/* Change the background color */
    body {
        background-color: #2c2f33 !important; /* Dark background */
        color: #ffffff !important; /* White text */
    }

    /* Style channel names */
    .channelName-3Q6Q1C {
        color: #7289da !important; /* Discord blurple */
    }

    /* Style the message input area */
    .slateTextArea-1Mkdgw {
        background-color: #40444b !important; /* Darker input background */
        color: #ffffff !important; /* Input text color */
    }

    /* Change link colors */
    a {
        color: #00bfff !important; /* Bright blue links */
    }

    /* Change hover effect on links */
    a:hover {
        text-decoration: underline !important; /* Underline on hover */
    }

    /* Style for buttons */
    .button-1PI7QZ {
        background-color: #7289da !important; /* Button color */
        color: #ffffff !important; /* Button text color */
    }

    /* Hover effect for buttons */
    .button-1PI7QZ:hover {
        background-color: #5a6eaa !important; /* Darker on hover */
    }
}
